/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"bassstation-level-10","number":10,"title":"Envelopes, Triggering Modes & Extended Envelope Looping","skillBand":"Textbook","duration":"From the course textbook","summary":"- Master the physical 30 mm tactile faders governing the four-stage ADSR (Attack, Decay, Sustain, Release) envelope curves. - Apply official User Guide empirical timing landmarks across all envelope fader stages.","modules":[{"id":"bassstation-m-10-1","code":"10","title":"Envelopes, Triggering Modes & Extended Envelope Looping","blurb":"- Master the physical 30 mm tactile faders governing the four-stage ADSR (Attack, Decay, Sustain, Release) envelope curves. - Apply official User Guide empirical timing landmarks across all envelope fader stages.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"bassstation-l-o-10","title":"Section overview","blocks":[{"type":"step","title":"Section 10.1 — Amplitude and Modulation Envelopes","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Master the physical 30 mm tactile faders governing the four-stage ADSR (Attack, Decay, Sustain, Release) envelope curves.","Apply official User Guide empirical timing landmarks across all envelope fader stages.","Operate the <strong>Env Select</strong> multiplexer switch to edit the <strong>Amp Envelope</strong>, <strong>Modulation Envelope</strong>, or both generators simultaneously.","Map the functional routing destinations of the Modulation Envelope across pitch, pulse width, and filter cutoff stages."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-10-1-1","title":"10.1.1: ADSR Fader Architecture and Timing Calibration","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II incorporates two independent, high-speed four-stage analogue/digital hybrid ADSR envelope generators:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  ADSR ENVELOPE STAGES &amp; HARDWARE TIMINGS\n   Level\n    ▲            /\\\n    │           /  \\\n 100│          /    \\\n    │         /      \\_______________ (Sustain Level: 0 to 100%)\n    │        /                       \\\n    │       /                         \\\n    │      /                           \\\n  0 └─────┴────────┬────────────────────┴──────► Time\n       [Attack]  [Decay]             [Release]\n       (Mid≈250ms)(Mid≈150ms)        (Mid≈360ms / Max &gt; 10s)</pre>"},{"type":"list","items":["<strong>Attack (Time)</strong>:","Sets the time taken for envelope voltage to rise from 0 to 100% peak upon Note-On.","<em>Minimum</em>: Sub-millisecond (instantaneous click/transient).","<em>Mid-Position</em>: <strong>Approximately 250 ms (0.25 seconds)</strong>.","<em>Maximum</em>: &gt; 5 seconds (slow, gradual ambient swell).","<strong>Decay (Time)</strong>:","Sets the time taken for voltage to drop from 100% peak down to the Sustain level.","<em>Minimum</em>: Instantaneous drop.","<em>Mid-Position</em>: <strong>Approximately 150 ms (0.15 seconds)</strong>.","<em>Maximum</em>: &gt; 5 seconds.","<strong>Sustain (Level)</strong>:","Sets the continuous voltage amplitude level maintained as long as the key is physically held down.","Unlike Attack, Decay, and Release (which are <em>time</em> parameters), Sustain is a pure <em>voltage level</em> (0% to 100%).","<strong>Release (Time)</strong>:","Sets the time taken for voltage to decay from the active sustain level back to zero after Note-Off.","<em>Minimum</em>: Instantaneous cutoff (organ-style gating).","<em>Mid-Position</em>: <strong>Approximately 360 ms (0.36 seconds)</strong>.","<em>Maximum</em>: <strong>Exceeds 10 seconds</strong> (long, lush, lingering acoustic tails)."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Load Init patch <code>64</code>. Set <strong>Env Select</strong> to <strong>Amp</strong>.","Position the <strong>Attack</strong> fader exactly at its mid-point (50%). Strike a key; verify that the volume takes ~250 ms to swell to full amplitude.","Position the <strong>Release</strong> fader fully up (100%). Strike and release a key; time the lingering release tail (verify it exceeds 10 seconds)."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-1-2","title":"10.1.2: Envelope Selection","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The <strong>Env Select</strong> slide switch assigns the physical ADSR faders to the two onboard envelope generators:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  ENV SELECT MULTIPLEXING LOGIC\n ┌────────────────────────────────────────────────────────────────────────┐\n │ [Env Select Switch]                                                    │\n │   ├── AMP  ──► Faders adjust Amplitude Envelope (Hardwired to VCA)     │\n │   ├── MOD  ──► Faders adjust Modulation Envelope (Routable Matrix)     │\n │   └── BOTH ──► Faders adjust BOTH Amp and Mod Envelopes simultaneously │\n └────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Amp Envelope</strong>: Dedicated to driving the Voltage Controlled Amplifier (VCA), shaping overall note volume dynamics.","<strong>Mod Envelope</strong>: Dedicated to dynamic parameter modulation across synthesis sections.","<strong>Both (Amp + Mod)</strong>: Links both generators, allowing simultaneous ADSR contour adjustments for rapid, uniform sound sculpting.","<strong>Parameter Retention</strong>: Modifying the faders on <strong>Amp</strong>, switching to <strong>Mod</strong>, and moving the faders modifies Mod <em>without altering the previously stored Amp ADSR values</em>."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Set <strong>Env Select</strong> to <strong>Amp</strong>: Program an instant attack, zero decay, 100% sustain, instant release (gate).","Set <strong>Env Select</strong> to <strong>Mod</strong>: Program an instant attack, 30% decay, 0% sustain, instant release (percussive pluck).","Route Mod Env to Filter Cutoff (depth 64) with the filter closed.","Play sustained notes; confirm that the filter snaps shut percussively via Mod Env while the note's volume remains sustained indefinitely via Amp Env."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-1-3","title":"10.1.3: Modulation Envelope Destination Matrix","blocks":[{"type":"step","title":"10.1.3: Modulation Envelope Destination Matrix","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"The Modulation Envelope can be routed simultaneously to three distinct synthesis blocks:"},{"type":"list","items":["<strong>Oscillator Pitch</strong>: Via the <strong>Mod Env</strong> rotary pot in the Oscillator section (positive or inverted pitch sweeps on Osc 1 and Osc 2).","<strong>Pulse Width (PWM)</strong>: Via the <strong>Pulse Width</strong> pot when the <strong>PWM Source</strong> switch is set to <strong>Mod Env</strong>.","<strong>Filter Cutoff</strong>: Via the <strong>Mod Env</strong> rotary pot in the Filter section (positive or inverted cutoff sweeps)."],"ordered":true}]},{"type":"step","title":"Section 10.2 — Triggering Modes and Extended Multi-Press Envelope Features","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Master the three primary keyboard triggering modes: <strong>Single</strong>, <strong>Multi</strong>, and <strong>Autoglide</strong>.","Apply strict definitions of <strong>Legato</strong> articulation across envelope re-triggering and portamento glide.","Program continuous <strong>Envelope Retriggering</strong> (<code>r-0</code> / <code>r-1</code>) for LFO-style envelope cycling.","Calibrate the <strong>Retrigger Count</strong> parameter (<code>c-0</code> to <code>c-16</code>).","Program <strong>Fixed-Duration Sustain</strong> (<code>d-0</code> / <code>d-1</code>) for drum, percussive, and one-shot acoustic sound design.","Enforce the fundamental operational override rule: Fixed Duration Sustain overrides Envelope Retriggering."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-10-2-1","title":"10.2.1: Single Triggering Mode","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Operational Logic</strong>:","In <strong>Single</strong> trigger mode, the envelope generators trigger from the beginning of their Attack stage <strong>only when a note is played from a detached (non-overlapping) state</strong>.","<strong>Legato Articulation</strong>:","If a new key is struck while the previous key is still held down (legato playing), the pitch changes immediately to the new note, but <strong>the envelopes DO NOT re-trigger</strong>. The sound continues sounding at its current Sustain/Decay level without restarting its Attack cycle.","<strong>Portamento Interaction</strong>:","If the <strong>Glide Time</strong> potentiometer is greater than zero, pitch glides smoothly between notes on <strong>every note transition</strong> (both detached and legato)."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Set <strong>Triggering</strong> switch to <strong>Single</strong>. Set Mod Env to open filter cutoff with a slow Attack (50%).","Play detached notes; observe the filter swell on every strike.","Play overlapping (legato) notes; observe that the filter does not re-swell on the second note."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-2-2","title":"10.2.2: Multi Triggering Mode","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Operational Logic</strong>:","In <strong>Multi</strong> trigger mode, the envelope generators <strong>re-trigger from their Attack stage on EVERY key strike</strong>, regardless of whether the notes are played legato (overlapping) or detached.","<strong>Musical Utility</strong>:","The standard baseline mode for aggressive synth stabs, arpeggiated basslines, and articulate keyboard solos where every note strike must have a sharp, punchy acoustic attack."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-2-3","title":"10.2.3: Autoglide Triggering Mode","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Operational Logic</strong>:","<strong>Autoglide</strong> combines Single-trigger envelope behavior with intelligent, performance-sensitive portamento glide:","<strong>Detached Notes</strong>: Play with instant, unglided pitch jumps.","<strong>Legato Notes (Overlapping)</strong>: Activate smooth portamento pitch glide between notes while preventing envelope re-triggering.","<strong>Musical Application</strong>:","The authoritative setting for expressive mono synth basslines, acid slides, and realistic acoustic woodwind/brass phrasing."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    TRIGGERING MODE COMPARISON MATRIX                       │\n├────────────┬─────────────────────────────┬─────────────────────────────────┤\n│ Mode       │ Non-Legato (Detached Notes) │ Legato (Overlapping Notes)      │\n├────────────┼─────────────────────────────┼─────────────────────────────────┤\n│ Single     │ Envelopes Re-trigger; Glide │ Envelopes DO NOT Re-trigger;    │\n│            │ active if Glide &gt; 0         │ Glide active if Glide &gt; 0       │\n├────────────┼─────────────────────────────┼─────────────────────────────────┤\n│ Multi      │ Envelopes Re-trigger; Glide │ Envelopes RE-TRIGGER; Glide     │\n│            │ active if Glide &gt; 0         │ active if Glide &gt; 0             │\n├────────────┼─────────────────────────────┼─────────────────────────────────┤\n│ Autoglide  │ Envelopes Re-trigger; ZERO  │ Envelopes DO NOT Re-trigger;    │\n│            │ Glide (Instant Pitch Jump)  │ GLIDE ACTIVATES SMOOTHLY        │\n└────────────┴─────────────────────────────┴─────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"bassstation-l-10-2-4","title":"10.2.4: Strict Legato Definition","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["In keyboard performance and hardware microprocessor scanning, <strong>Legato</strong> is defined strictly as <strong>temporal note overlap</strong>: \\[ \\text{Note-On}_{\\text{Key 2}} &lt; \\text{Note-Off}_{\\text{Key 1}} \\]","If even a 1-millisecond gap of physical silence exists between releasing Key 1 and depressing Key 2, the hardware registers a detached transition and executes a full envelope re-trigger."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-10-2-5","title":"10.2.5: Envelope Retriggering / Looping","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Envelope Retriggering converts the standard one-shot ADSR envelope into a continuous, looping pseudo-LFO waveform:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                    ENVELOPE RETRIGGERING (LOOPING)\n   Attack ──► Decay ──► (Instantly Loops back to Attack) ──► Attack ──► Decay...</pre>"},{"type":"list","items":["<strong>Operational Logic</strong>:","When <strong><code>r-1</code> (On)</strong> is active, once the envelope completes its Attack and Decay stages, it immediately cycles back and triggers the Attack stage again as long as the key is held down.","The looping rate is determined entirely by the sum of the <strong>Attack Time + Decay Time</strong>.","Because ADSR stages can be adjusted to fractions of a millisecond, envelope retriggering can reach audio-rate frequencies (&gt; 100 Hz), generating complex FM modulation textures with custom non-linear attack/decay slopes.","<strong>Activation Gesture</strong>:","Press <strong>Function / Exit</strong>, then <strong>press the Amp-Env key or Mod-Env key twice</strong> (lower <code>A#</code> or <code>B</code>).","Display indicates <code>r-0</code> (Off) or <code>r-1</code> (On). Toggle using <strong>Patch/Value ▲ and ▼</strong>.","Can be enabled independently for Amp Env and Mod Env."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Set Mod Env Attack to 10% and Decay to 20% with Sustain at 0.","Access the Mod Env Retrigger menu (<code>Function</code> + double-tap <code>Mod-Env</code> key). Set to <code>r-1</code>.","Route Mod Env to Filter Cutoff (depth 64) with filter closed.","Hold a key; observe the filter cutoff pulsate continuously in a tight rhythmic loop as long as the key is held."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-2-6","title":"10.2.6: Retrigger Count Calibration","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Operational Logic</strong>:","By default, an envelope with retrigger enabled loops infinitely (<code>c-0</code>) until the key is released.","The <strong>Retrigger Count</strong> function limits the loop to an exact finite burst of envelope cycles per note strike.","<strong>Parameter Values</strong>:","<strong><code>c-0</code></strong>: Infinite continuous looping (Default).","<strong><code>c-1</code> to <code>c-16</code></strong>: Exactly 1 to 16 discrete envelope loop cycles per key strike.","<strong>Sound Design Utility</strong>:","Program precise double-strikes (<code>c-2</code>), triple-bursts (<code>c-3</code>), or ratcheting percussive rolls that automatically terminate after the programmed count.","<strong>Activation Gesture</strong>:","Press <strong>Function / Exit</strong>, then <strong>press the Amp-Env or Mod-Env key THREE times</strong>.","Display indicates <code>c-0</code> through <code>c-16</code>. Adjust using <strong>Patch/Value ▲ and ▼</strong>.","<strong>Support Rule</strong>:","Retrigger Count has no effect unless Envelope Retriggering is set to <code>r-1</code>."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-10-2-7","title":"10.2.7: Fixed-Duration Sustain and The Master Override Rule","blocks":[{"type":"step","title":"10.2.7: Fixed-Duration Sustain and The Master Override Rule","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"Fixed-Duration Sustain transforms the ADSR envelope into an ADR/AHD one-shot generator, completely eliminating traditional key-held sustain:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  FIXED-DURATION SUSTAIN ARCHITECTURE\n   [Note-On Strike] ──► [Attack Stage] ──► [Sustain Stage: FIXED DURATION] ──► [Release]\n                                            ▲\n                                            │ (Decay Fader Sets TIME DURATION)\n                                    [Decay Fader Position]</pre>"},{"type":"list","items":["<strong>Operational Logic</strong>:","When <strong><code>d-1</code> (On)</strong> is active, holding a key down does not maintain continuous sustain.","The <strong>Decay fader changes function</strong>: it no longer controls decay rate; instead, it <strong>sets the exact time duration that the envelope remains at maximum sustain level</strong>.","Once that fixed time duration elapses, the envelope immediately drops to zero through the Release stage, <strong>even if the user continues to hold down the key</strong>.","<strong>Sound Design Utility</strong>:","Perfect for synthesizing acoustic drums, kicks, snares, claps, and one-shot sound effects where notes must have identical, fixed durations regardless of keyboard finger technique.","<strong>Activation Gesture</strong>:","Press <strong>Function / Exit</strong>, then <strong>press the Amp-Env or Mod-Env key FOUR times</strong>.","Display indicates <code>d-0</code> (Off) or <code>d-1</code> (On).","<strong>The Master Override Rule (Official Novation Architecture)</strong>: &gt; [!IMPORTANT] &gt; <strong>Fixed-Duration Sustain (<code>d-1</code>) completely OVERRIDES and DISABLES Envelope Retriggering (<code>r-1</code>)</strong>. &gt; If both <code>r-1</code> and <code>d-1</code> are enabled on the same envelope, the envelope will execute a single fixed-duration shot and will <strong>NOT loop</strong>. To restore envelope looping, Fixed-Duration Sustain must be set to <code>d-0</code>."],"ordered":true},{"type":"heading","text":"2. Hardware Verification & Practical Exercise","level":4},{"type":"list","items":["On an Init patch, access the Amp Env menu with 4 presses; set to <code>d-1</code>.","Move the <strong>Decay</strong> fader to 25%.","Strike and hold Middle C firmly.","Observe that the sound plays for a precise fraction of a second and cuts off completely while your finger is still holding down the key.","Move Decay to 75%; strike and hold; observe the note duration lengthen proportionally."],"ordered":true}]},{"type":"step","title":"Assessment Gate F — Self-Assessment Checkpoint","blocks":[{"type":"prose","html":"Before advancing to Module 11, verify complete mastery of Gate F proficiencies:"},{"type":"list","items":["[ ] <strong>Independent ADSR Sculpting</strong>: Program distinct, independent contours for the Amp Envelope (slow swell pad) and Mod Envelope (sharp percussive pluck).","[ ] <strong>Triggering Demonstration</strong>: Demonstrate the audible difference between Single, Multi, and Autoglide triggering while playing legato phrases with Glide active.","[ ] <strong>Envelope Looping Execution</strong>: Enable Envelope Retriggering (<code>r-1</code>) using the 2-press Function gesture and demonstrate continuous cutoff looping.","[ ] <strong>Retrigger Count Burst</strong>: Configure Retrigger Count to <code>c-3</code> using the 3-press gesture and demonstrate a 3-cycle ratcheting burst.","[ ] <strong>Fixed-Duration Sustain &amp; Override</strong>: Enable Fixed-Duration Sustain (<code>d-1</code>) using the 4-press gesture, demonstrate one-shot percussive gating, and state the override rule regarding envelope looping."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
